def kenya_ring():
    """Closed ring of [lon, lat] points for a GeoJSON polygon."""
    pts = re.findall(r"(-?[0-9.]+),(-?[0-9.]+)", _PATH)
    return [[MIN_LON + float(x) / SCALE, MAX_LAT - float(y) / SCALE] for x, y in pts]


